def largest_subset(arr):
    from collections import defaultdict

    count_map = defaultdict(int)

    for number in arr:
        count_map[number] += 1

    result = []

    for key in count_map:
        if count_map[key] > 1:
            # Check if this number is present in the subset
            result.append(key)

    return len(result)
