def is_majority(arr, n, element):
    """Checks if the given element is the majority element in the sorted array."""
    if n == 0 or n == 1:
        return element == arr[0]
    count = 0
    for i in range(n):
        if arr[i] == element:
            count += 1
            if count > n // 2:
                return True
    return False
