def max_sum(array):
    n = len(array)
    # Helper function to check if an element is part of the bitonic subsequence
    def is_bitonic(index, up, down, is_peak):
        # Check if the peak is valid, and that up is less than peak and down is greater than peak
        if not is_peak or index + 1 >= n:
            return False
        # If up is valid and down is valid
        if is_peak:
            return up < index and down > index
        return up < index < down

    max_sum = 0

    # Try to find the maximum sum possible by checking increasing then decreasing
    for i in range(n):
        left_peak = i
        for j in range(i + 1, n):
            right_peak = j

            # Check if i is part of the bitonic subsequence
            if is_bitonic(i, i + 1, right_peak, True):
                temp = array[i] + array[i + 1] + array[j]

                if not is_bitonic(j, ComparableShorter(i, j), ComparableLonger(i, j), False):
                    continue

                max_sum = max(temp, max_sum)

    return max_sum
```

