def max_bitonic_sum(arr):
    n = len(arr)
    # We'll use dynamic programming to solve this problem.
    dp = [i for i in range(n)]
    for i in range(n):
        for j in range(i, n):
            if arr[j] > arr[j-1]:
                if j == i:
                    # Single element is trivially bitonic
                    dp[i] = arr[i]
                else:
                    if dp[i] > arr[j] and dp[j] > arr[j-1]:
                        dp[j] = max(dp[j], dp[i], arr[j])
                    elif dp[i] > arr[j] or dp[j] > arr[j-1]:
                        dp[j] = max(dp[j], arr[j])
                    else:
                        dp[j] = max(dp[j], arr[i])

    # The sum of the maximum bitonic subsequence
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, dp[i])
    return max_sum
```

