def next_power_of_2(n):
    if n == 0:
        return 1
    num = n
    i = 2
    while (1 << i) < num:
        i += 1
    # Now 1 << (i - 1) is the next power of 2 less than num
    power = 1 << (i - 1)
    return power if power <= num else (1 << i)
```

```python
def next_power_of_2(n):
    if n == 0:
        return 1
    # Find the smallest power of 2 >= n
    half = 1 << (n.bit_length())
    if (half & (half - 1)) == 0:
        return half
    # Check if n is a power of 2
    if (n & (n - 1)) != 0:
        return 1 << (n.bit_length() - 1)
    return half
```

