def sum_Of_product(n):
    result = 0
    for i in range(0, n + 1):
        for j in range(i, n + 1):
            term = 1
            for k in range(i, j + 1):
                term *= combination(n, k)
            result += term * combination(n, j - i)
    return result

def combination(n, k):
    if k < 0 or k > n:
        return 0
    from math import comb
    result = comb(n, k)
    if result < 0:
        result = 0
    return result

