def sum_Of_product(n):
    result = 0
    for i in range(0, n + 1):
        for j in range(i, n + 1):
            product = 1
            for k in range(i, j + 1):
                product *= comb(k, i)
            result += product
    return result

def comb(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
